const sheets = $json.sheets || [];

return sheets.map(s => ({
  json: {
    sheetName: s.properties.title,
    sheetId: s.properties.sheetId
  }
}));

return items.map(item => {
  const data = item.json;

  const headers = data.values?.[0] || [];

  const sheetName = String(data.range || "")
    .split("!")[0]
    .replace(/^'/, "")
    .replace(/'$/, "");

  const fieldCount = headers.length;

  return {
    json: {
      sheetName,
      fieldCount,
      resolution: fieldCount <= 3 ? "new" : "old"
    }
  };
});

return items.map(item => {
  const data = item.json;
  const row = data.values?.[0] || [];

  const sheetName = String(data.range || "")
    .split("!")[0]
    .replace(/^'/, "")
    .replace(/'$/, "");

  return {
    json: {
      sheetName,
      SKU: row[0] || "",
      Ссылка: row[1] || "",
      Фото: row[2] || ""
    }
  };
});

return items.map(item => {
  const row = item.json;

  const sku =
    row.SKU ||
    String(row["Ссылка"]).match(/\/catalog\/(\d+)\//)?.[1];

  const nm = Number(sku);
  const vol = Math.floor(nm / 100000);
  const part = Math.floor(nm / 1000);

  let basket = null;
  const photo = row["Фото"] || "";
  const m = String(photo).match(/basket-(\d+)\.wbbasket/);
  if (m) basket = m[1].padStart(2, "0");

  if (!basket) {
    throw new Error(`Нет basket в ссылке фото для SKU ${sku}`);
  }

  return {
    json: {
      ...row,
      Артикул: sku,
      cardJsonUrl: `https://basket-${basket}.wbbasket.ru/vol${vol}/part${part}/${nm}/info/ru/card.json`,
    }
  };
});

const BASE_HEADERS = [
  "SKU",
  "Ссылка",
  "Фото",
  "Артикул",
  "Название",
  "Категория 1",
  "Категория 2",
  "Бренд"
];

function addHeader(headers, name) {
  if (name && name !== "Фото" && !headers.includes(name)) {
    headers.push(name);
  }
}

function collectHeaders(card) {
  const headers = [...BASE_HEADERS];
  for (const opt of card.options || []) { addHeader(headers, opt?.name); }
  for (const group of card.grouped_options || []) {
    for (const opt of group.options || []) { addHeader(headers, opt?.name); }
  }
  return headers;
}

const sourceItems = $items("Code in JavaScript3");

return items.map((item, index) => {
  const source = sourceItems[index]?.json || {};
  return {
    json: {
      sheetName: source.sheetName,
      headers: collectHeaders(item.json)
    }
  };
});

return items.flatMap(item => {
  const data = item.json;
  const values = data.values || [];
  if (values.length < 2) return [];
  const headers = values[0];
  const sheetName = String(data.range || "").split("!")[0].replace(/^'/, "").replace(/'$/, "");
  const nameIndex = headers.indexOf("Название");
  const result = [];
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    const rowNumber = i + 1;
    const sku = String(row[0] || "").trim();
    const link = String(row[1] || "").trim();
    const photo = String(row[2] || "").trim();
    const title = nameIndex >= 0 ? String(row[nameIndex] || "").trim() : "";
    const first3Filled = sku !== "" && link !== "" && photo !== "";
    const titleEmpty = nameIndex === -1 || title === "";
    if (first3Filled && titleEmpty) {
      result.push({ json: { sheetName, rowNumber, SKU: sku, Ссылка: link, Фото: photo, headers } });
    }
  }
  return result;
});

return items.map(item => {
  const row = item.json;
  const sku = row.SKU || String(row["Ссылка"]).match(/\/catalog\/(\d+)\//)?.[1];
  const nm = Number(sku);
  const vol = Math.floor(nm / 100000);
  const part = Math.floor(nm / 1000);
  let basket = null;
  const photo = row["Фото"] || "";
  const m = String(photo).match(/basket-(\d+)\.wbbasket/);
  if (m) basket = m[1].padStart(2, "0");
  if (!basket) throw new Error(`Нет basket в ссылке фото для SKU ${sku}`);
  return { json: { ...row, Артикул: sku, cardJsonUrl: `https://basket-${basket}.wbbasket.ru/vol${vol}/part${part}/${nm}/info/ru/card.json` } };
});

const BASE_HEADERS=["SKU","Ссылка","Фото","Артикул","Название","Категория 1","Категория 2","Бренд"];
function val(v){if(Array.isArray(v))return v.join("; ");if(v===null||v===undefined)return "";return String(v);}
function addHeader(headers,name){if(name&&name!=="Фото"&&!headers.includes(name))headers.push(name);}
function getAllOptions(card){const map=new Map();for(const opt of card.options||[]){if(opt?.name)map.set(opt.name,val(opt.value));}for(const group of card.grouped_options||[]){for(const opt of group.options||[]){if(opt?.name&&!map.has(opt.name))map.set(opt.name,val(opt.value));}}return map;}
return items.map(item=>{const card=item.json;const sku=String(card.SKU||card["Артикул"]||card.nm_id||card.nmId||"");const row={SKU:sku,Артикул:sku,Ссылка:card["Ссылка"]||(sku?`https://www.wildberries.ru/catalog/${sku}/detail.aspx`:""),Название:card.imt_name||card.imtName||card.name||"","Категория 1":card.subj_name||card.subjectName||"","Категория 2":card.subj_root_name||card.parentName||"",Бренд:card.selling?.brand_name||card.brand||card.brand_name||""};const writeHeaders=[...BASE_HEADERS];const optionsMap=getAllOptions(card);for(const[name,value]of optionsMap.entries()){if(name==="Фото")continue;row[name]=value;addHeader(writeHeaders,name);}return{json:{...row,writeHeaders}};});

const filter1Items = $('Filter1').all();
const seen = new Map();
for (const item of items) {
  const pairedIdx = typeof item.pairedItem === 'number' ? item.pairedItem : (item.pairedItem?.item ?? 0);
  if (!seen.has(pairedIdx)) {
    const sheetName = filter1Items[pairedIdx]?.json?.sheetName ?? '';
    seen.set(pairedIdx, { json: { ...item.json, sheetName } });
  }
}
return Array.from(seen.values());

const allSheets = $('Code in JavaScript').all().map(i => i.json.sheetName);
const filtered = items.filter(item => {
  const newName = item.json['Категория 1'];
  const currentName = item.json.sheetName;
  return !allSheets.some(name => name === newName && name !== currentName);
});
const seenTargets = new Set();
return filtered.filter(item => {
  const newName = item.json['Категория 1'];
  if (seenTargets.has(newName)) return false;
  seenTargets.add(newName);
  return true;
});

